package com.kisanprocure.repository; import com.kisanprocure.entity.Centre; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface CentreRepository extends JpaRepository<Centre,Long>{ @Query("select c from Centre c where c.status = com.kisanprocure.entity.enums$CentreStatus.ACTIVE and (6371 * acos(cos(radians(:lat)) * cos(radians(c.latitude)) * cos(radians(c.longitude) - radians(:lng)) + sin(radians(:lat)) * sin(radians(c.latitude)))) <= :radiusKm") List<Centre> findNearby(@Param("lat") double lat,@Param("lng") double lng,@Param("radiusKm") double radiusKm); }